- Task 2: one extra test 'counts the sentences of a multi-line passage' asserting sentenceCount(PASSAGE) === 8 using the brief's PASSAGE constant (currently defined but unused in the brief's test file), placed before the reference-table test; 9 tests in test/sentenceCount.test.js, 18 suite-wide (the brief's "8 from Task 1"/"16 tests" counts predate the Task 1 extra test).
- Task 3: two extra tests in test/topWords.test.js, placed before the reference-table test: (a) 'ranks the words of a multi-line passage' asserting topWords(PASSAGE, 20) deep-equals the full 11-entry ranking keeper 3, lamp 3, night 2, tower 2, climbed 1, hand 1, lit 1, old 1, older 1, shook 1, storm 1 (uses the brief's PASSAGE constant, otherwise unused; verified by hand); (b) 'throws a RangeError naming the function for an invalid n' looping over [undefined, NaN, '3', 1.5, -1] with text 'apple', asserting RangeError and the 'topWords:' prefix. 10 tests in the file, 28 suite-wide (the brief's "16 earlier"/"24 tests" counts predate the Task 1 and 2 extras).
// A word is a run of letters or digits (any script), optionally joined to the
// next run by a single apostrophe (straight or typographic) or hyphen. The
// joiners are only part of a word when letters or digits sit on both sides, so
// a trailing "well-" or "dogs'" loses its joiner. Everything else, including
// em dashes, periods and underscores, separates words.
const WORD_PATTERN = /[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu;

function assertText(fn, value) {
  if (typeof value !== 'string') {
    throw new TypeError(`${fn}: text must be a string, received ${value === null ? 'null' : typeof value}`);
  }
}

// Private: the single definition of "word" shared by every statistic below.
function tokenize(text) {
  return text.match(WORD_PATTERN) ?? [];
}

/**
 * Count the words in a piece of text.
 *
 * @param {string} text
 * @returns {number}
 */
function wordCount(text) {
  assertText('wordCount', text);
  return tokenize(text).length;
}

